import {RECIPES} from './catalog.mjs';
const TAU=Math.PI*2;
export function drawGunDrop(c,d,t){const a=RECIPES[d.gunType],y=d.y+Math.sin(t*3)*3;c.save();c.translate(d.x,y);const glow=c.createRadialGradient(0,0,3,0,0,45);glow.addColorStop(0,a.color+'77');glow.addColorStop(1,a.color+'00');c.fillStyle=glow;c.beginPath();c.arc(0,0,45,0,TAU);c.fill();c.fillStyle='#142e2b';c.strokeStyle=a.color;c.lineWidth=2;c.fillRect(-22,-14,44,28);c.strokeRect(-22,-14,44,28);c.fillStyle=a.color;c.fillRect(-13,-4,29,7);c.fillRect(-6,3,7,8);c.fillRect(13,-6,5,11);c.font='bold 11px sans-serif';c.textAlign='center';c.strokeStyle='#10251c';c.lineWidth=3;c.strokeText(a.name,0,-24);c.fillText(a.name,0,-24);c.font='10px sans-serif';c.fillText('靠近拾取 · 化学枪',0,33);c.restore()}
export function drawEvolutionZone(c,z,t){c.save();c.translate(z.x,z.y);if(z.kind==='fire'){c.globalAlpha=Math.min(1,z.life);const g=c.createRadialGradient(0,0,2,0,0,z.radius);g.addColorStop(0,'#dcf5ff88');g.addColorStop(.5,'#899aff66');g.addColorStop(1,'#6699ff00');c.fillStyle=g;c.beginPath();c.arc(0,0,z.radius,0,TAU);c.fill();for(let i=0;i<8;i++){const a=i*TAU/8,x=Math.cos(a)*z.radius*.6,y=Math.sin(a)*z.radius*.5,h=12+Math.sin(t*14+i)*7;c.beginPath();c.moveTo(x-4,y);c.quadraticCurveTo(x-6,y-h/2,x+Math.sin(t*8+i)*5,y-h);c.quadraticCurveTo(x+6,y-h/3,x+4,y);c.fillStyle=i%2?'#8bb9ff':'#d7f6ff';c.fill()}}
 else if(z.kind==='node'){c.strokeStyle='#e7c1ff';c.lineWidth=2;c.beginPath();c.arc(0,0,11+Math.sin(t*10)*2,0,TAU);c.stroke();c.fillStyle='#eee2ff';c.font='bold 17px sans-serif';c.textAlign='center';c.fillText('ϟ',0,6)}
 else{const vortex=z.kind==='vortex';c.rotate(t*(vortex?5:1));for(let i=0;i<(vortex?5:3);i++){c.strokeStyle=i%2?'#efffdabb':'#9ad9c077';c.lineWidth=vortex?5:8;c.beginPath();c.arc(0,0,z.radius*(.25+i*.15),i*1.3,i*1.3+Math.PI*1.5);c.stroke()}if(vortex){c.fillStyle='#d6f5d544';c.beginPath();c.arc(0,0,z.radius,0,TAU);c.fill()}else{c.rotate(Math.atan2(z.vy,z.vx)-t);c.strokeStyle='#f1ffdb';c.lineWidth=3;c.beginPath();c.moveTo(-40,0);c.lineTo(18,0);c.stroke()}}
 c.restore()}
export function drawEvolutionProjectile(c,b,t){if(!b.evolution)return false;if(b.evolution==='waterPulse'){c.save();c.translate(b.x,b.y);c.rotate(Math.atan2(b.vy,b.vx));c.strokeStyle='#76eaff66';c.lineWidth=22;c.beginPath();c.arc(-10,0,26,-.9,.9);c.stroke();c.strokeStyle='#e1ffff';c.lineWidth=5;c.stroke();c.restore();return true}if(b.evolution==='giantRail'){c.save();c.translate(b.x,b.y);c.rotate(Math.atan2(b.vy,b.vx));c.strokeStyle='#a7d7ff66';c.lineWidth=26;c.beginPath();c.moveTo(-90,0);c.lineTo(8,0);c.stroke();c.strokeStyle='#e4f4ff';c.lineWidth=10;c.stroke();c.strokeStyle='#fff';c.lineWidth=3;c.stroke();c.restore();return true}return false}
export function drawSecondGun(c,r,t){const w=r.weapons?.[1];if(!w?.gun)return;const a=w.angle;c.save();c.translate(r.x,r.y);c.rotate(a);c.translate(0,-12);c.fillStyle=RECIPES[w.gun.type]?.color||'#b9c7a3';c.fillRect(12,-4,30,8);c.strokeStyle='#233e30';c.lineWidth=2;c.strokeRect(12,-4,30,8);if(w.gun.rank>=5){c.fillRect(21,-7,5,14);c.fillRect(29,-7,5,14)}if(w.gun.rank>=10){c.strokeStyle='#eff9d7';c.lineWidth=2;c.strokeRect(36,-7,12,14)}c.restore()}
